package x;
import java.util.*;

public class Player {
	private String name;
	private int goals;

	public Player(String name, int goals) {
		this.name = name;
		this.goals = goals;
	}
	public String getName() { return name; }
	public int getGoals() { return goals; }
	public String toString() { return name + "(" + goals + ")"; }
}

public class Team {
    private String name;
    private Player[] players;
    private int count;

    public Team(String name) {
        this.name = name;
        this.players = new Player[11];
        this.count = 0;
    }
    public String getName() { return name; }
    public void add(Player p) { if (count < players.length) players[count++] = p; }
    public Player[] getPlayers() { return players; }
    public int getCount() { return count; }
    public String toString() { return name + " " + count + " שחקנים"; }
}

